// Conversations share the app's browser-local storage and booking policies.
function messageViewer(){return state.role==='Barber Pro'?'barber:'+activeBarberId():state.role;}
function canViewThread(t){return !!t&&(state.role==='Owner HQ'||(state.role==='Customer'?t.client==='John B.':t.kind==='barber'&&t.barber===activeBarberId()));}
function ownMessage(m){return m.role===state.role;}
function unreadMessages(t){return t.messages.filter(m=>!ownMessage(m)&&!(m.readBy||[]).includes(messageViewer())).length;}
function messageRead(m,t){const recipient=m.role==='Customer'?(t.kind==='general'?'Owner HQ':'barber:'+t.barber):'Customer';return (m.readBy||[]).includes(recipient);}
function readThread(t){let changed=false;for(const m of t.messages){m.readBy=m.readBy||[];if(!m.readBy.includes(messageViewer())){m.readBy.push(messageViewer());changed=true;}}if(changed)save();}
function postAppointment(t,b,title){if(!t)return;t.messages.push({role:state.role,name:state.role==='Customer'?'John B.':state.role==='Barber Pro'?activeStaff().name:'Shop owner',body:title,at:Date.now(),delivered:true,readBy:[messageViewer()],appointment:{id:b.id,title,date:b.date,time:b.time,service:bookingName(b),location:b.location}});}
function walkInTime(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Phoenix',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const now=Number(parts.hour)*60+Number(parts.minute);const time=times.find(t=>minutes(t)>=now);if(!time)throw Error('No walk-in times remain today. Choose an appointment.');return time;}
if(!clientRecords.some(c=>c.name==='Marcus Reed'))clientRecords.push({name:'Marcus Reed',visits:0,note:'First visit · textured crop.',img:null},{name:'Daniel Lee',visits:4,note:'Classic taper.',img:null});
if(!extras.messagingSeeded){
 const now=Date.now();
 for(const barber of barbers){
  for(const [i,client] of ['Alex Morgan','Ryan Smith','Marcus Reed','Daniel Lee'].entries()){
   const t=threadFor(client,barber.id);if(t.messages.length)continue;
   const texts=i===0?['Hey! Ready for a fresh cut.','Can we keep a little more length on top?','Do you have anything open tomorrow?']:i===1?['Could we move my next visit to the afternoon?']:i===2?['Hi! Can I book a haircut and beard trim?']:['Thanks for the cut. See you next time!'];
   t.messages=texts.map((body,j)=>({role:'Customer',name:client,body,at:now-600000-i*3600000+j*60000,readBy:['Customer',...(i===3?['barber:'+barber.id,'Owner HQ']:[])],delivered:true}));
  }
 }
 for(const t of extras.conversations)for(const m of t.messages){m.at=m.at||now-86400000;m.readBy=m.readBy||[m.role==='Barber Pro'?'barber:'+t.barber:m.role];m.delivered=true;}
 extras.messagingSeeded=true;save();
}
const bookingFormBeforeMessaging=manualBooking;
manualBooking=function(){let html=bookingFormBeforeMessaging();const t=extras.conversations.find(t=>t.id===state.bookingThread);if(t&&canViewThread(t)){html=html.replace('name="client"','name="client" value="'+esc(t.client)+'" readonly');html=html.replace('<select name="barber">','<select name="barber" disabled>');html=html.replace('<label class="field">Barber','<input type="hidden" name="barber" value="'+esc(t.barber)+'"><label class="field">Barber');}
 return html.replace('<label class="field">Date','<label class="field">Booking type<select name="bookingType"><option value="appointment">Appointment</option><option value="walk-in">Walk-in</option></select></label><p class="muted walk-in-note" hidden>Walk-ins use the next time slot today, subject to availability.</p><div class="appointment-fields"><label class="field">Date').replace('<p id="booking-error"','</div><p id="booking-error"');};
conversationInbox=function(){
 const role=state.role,allowed=extras.conversations.filter(canViewThread).sort((a,b)=>(b.messages.at(-1)?.at||0)-(a.messages.at(-1)?.at||0));
 const thread=allowed.find(t=>t.id===state.threadId);if(thread)readThread(thread);
 const name=t=>t.kind==='general'?'Shop inbox':role==='Customer'?(barbers.find(b=>b.id===t.barber)?.name||'Your barber'):t.client;
 const avatar=t=>role==='Owner HQ'?matchedPortraits(t.client,t.barber):role==='Customer'&&t.barber?photo(barbers.find(b=>b.id===t.barber)):clientPhoto(t.client);
 const linked=thread?bookings.filter(b=>b.client===thread.client&&b.barber===thread.barber&&['confirmed','pending_payment'].includes(b.status)&&!thread.messages.some(m=>m.appointment?.id===b.id)):[];
 const visible=state.unreadOnly?allowed.filter(t=>unreadMessages(t)):allowed;
 const unread=allowed.reduce((n,t)=>n+unreadMessages(t),0);
 return `${head('Messages.','Keep in touch before and after your visit.')}<div class="inbox-layout messenger"><section class="inbox-threads"><div class="inbox-filters"><button data-chat="all" aria-pressed="${!state.unreadOnly}">All messages</button><button data-chat="unread" aria-pressed="${!!state.unreadOnly}">Unread ${unread?`<span class="unread-badge">${unread}</span>`:''}</button></div>${role==='Barber Pro'?xbutton('New message','new-thread','secondary full'):''}${state.pickClient&&role==='Barber Pro'?clientRecords.map((c,i)=>`<button data-talk="new-client" data-index="${i}">${photo(c)} ${esc(c.name)}</button>`).join(''):''}${visible.map(t=>{const count=unreadMessages(t),last=t.messages.at(-1);return `<button class="thread-row ${thread?.id===t.id?'selected':''}" data-talk="select" data-id="${esc(t.id)}">${avatar(t)}<span class="thread-summary"><strong>${esc(name(t))}</strong><small>${last?new Date(last.at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):''}</small><p>${esc(last?.body||'Start a conversation')}</p></span>${count?`<span class="unread-dot" aria-hidden="true"></span><span class="unread-badge" aria-label="${count} unread messages">${count}</span>`:''}</button>`;}).join('')||'<p class="muted">No unread conversations.</p>'}</section><section class="panel conversation-panel">${thread?`<header class="row">${avatar(thread)}<h2>${esc(name(thread))}</h2>${isStaff()&&thread.kind==='barber'?`<button class="btn secondary small" data-chat="book" data-thread="${esc(thread.id)}">Create booking</button>`:''}</header>${linked.length?`<div class="linked-appointments">${linked.map(b=>`<article><div class="row">${appointmentPortrait(b)}<strong>${esc(bookingName(b))}</strong></div><p>${pretty(b.date)} · ${esc(b.time)}</p>${appointmentActions(b)}</article>`).join('')}</div>`:''}<div class="thread-history" role="log" aria-label="Message history">${thread.messages.map(m=>{const a=m.appointment,b=a&&bookings.find(b=>b.id===a.id);return `<div class="message-bubble ${ownMessage(m)?'out':''}"><small class="message-author">${esc(m.name)}</small>${a?`<article class="chat-appointment"><div class="row">${appointmentPortrait({client:thread.client,barber:thread.barber})}<strong>${esc(a.title)}</strong></div><h3>${esc(a.service)}</h3><p>${pretty(a.date)} · ${esc(a.time)}</p><p>${esc(shops[a.location]?.name||'Shop')}</p>${b&&b.date===a.date&&b.time===a.time?`<small>${esc(b.status.replaceAll('_',' '))}</small>${appointmentActions(b)}`:'<small>Previous appointment time</small>'}</article>`:`<div>${esc(m.body)}</div>`}<small class="message-receipt">${new Date(m.at||Date.now()).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}${ownMessage(m)?' · '+(messageRead(m,thread)?'Read':'Delivered'):''}</small></div>`;}).join('')||'<p class="muted">Start the conversation.</p>'}</div><form id="thread-message-form" class="message-form" data-thread="${esc(thread.id)}"><input name="body" aria-label="Message" placeholder="Message…" maxlength="1000" autocomplete="off" required><button class="btn" aria-label="Send message">${icon('send')}</button></form>${role==='Customer'?xbutton('Message shop','general-thread','secondary','style="margin-top:20px"'):''}`:'<h2>Your conversations</h2><p class="muted">Choose a conversation to read and reply.</p>'}</section></div>`;
};
document.addEventListener('change',e=>{if(e.target.matches('#manual-booking [name=bookingType]')){const f=e.target.form,walk=e.target.value==='walk-in';f.querySelector('.appointment-fields').hidden=walk;f.querySelector('.walk-in-note').hidden=!walk;f.elements.date.disabled=walk;f.elements.time.disabled=walk;}});
document.addEventListener('click',e=>{if(e.target.closest('[data-enhance=booking]'))state.bookingThread=null;const b=e.target.closest('[data-chat]');if(!b)return;if(b.dataset.chat==='book'){const t=extras.conversations.find(t=>t.id===b.dataset.thread);if(!isStaff()||!canViewThread(t))return;state.bookingThread=t.id;state.manualBarber=t.barber;go('manualBooking');}else{state.unreadOnly=b.dataset.chat==='unread';render();}});
const renderBeforeMessaging=render;render=function(){renderBeforeMessaging();if(['messages','pMessages','hMessages'].includes(state.view)){const history=document.querySelector('.thread-history');if(history)history.scrollTop=history.scrollHeight;}const unread=extras.conversations.filter(canViewThread).reduce((n,t)=>n+unreadMessages(t),0);if(unread)document.querySelectorAll('.side-nav [data-view="messages"],.side-nav [data-view="pMessages"],.side-nav [data-view="hMessages"],.bottom-nav [data-view="messages"],.bottom-nav [data-view="pMessages"],.bottom-nav [data-view="hMessages"]').forEach(el=>el.insertAdjacentHTML('beforeend',`<span class="unread-badge">${unread}</span>`));};
render();
